-- 2. TABLAS COMPLEMENTARIAS PARA TODAS LAS SECCIONES SCIENTI (GRUPLAC Y CVLAC)
CREATE TABLE IF NOT EXISTS public.grupo_instituciones (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    grupo_id bigint NOT NULL REFERENCES public.grupos(id) ON DELETE CASCADE,
    codigo_gruplac varchar(30) NOT NULL,
    nombre varchar(255) NOT NULL,
    avalado boolean NOT NULL DEFAULT true,
    texto_original text,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_grupo_institucion UNIQUE (codigo_gruplac, nombre)
);

CREATE TABLE IF NOT EXISTS public.grupo_plan_estrategico (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    grupo_id bigint NOT NULL REFERENCES public.grupos(id) ON DELETE CASCADE,
    codigo_gruplac varchar(30) NOT NULL,
    plan_trabajo text,
    estado_arte text,
    objetivos text,
    retos text,
    vision text,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_grupo_plan_estrategico UNIQUE (codigo_gruplac)
);

CREATE TABLE IF NOT EXISTS public.lineas_investigacion (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    grupo_id bigint REFERENCES public.grupos(id) ON DELETE CASCADE,
    investigador_id bigint REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_gruplac varchar(30),
    codigo_rh varchar(30),
    origen varchar(20) NOT NULL DEFAULT 'GrupLAC',
    numero integer NOT NULL DEFAULT 1,
    nombre varchar(255) NOT NULL,
    activa boolean NOT NULL DEFAULT true,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_linea_investigacion UNIQUE (origen, nombre)
);

CREATE TABLE IF NOT EXISTS public.investigador_formacion (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    investigador_id bigint NOT NULL REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_rh varchar(30) NOT NULL,
    tipo_formacion varchar(40) NOT NULL,
    nivel varchar(80) NOT NULL,
    descripcion text NOT NULL,
    anio integer,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_investigador_formacion UNIQUE (codigo_rh, descripcion)
);

CREATE TABLE IF NOT EXISTS public.investigador_experiencia (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    investigador_id bigint NOT NULL REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_rh varchar(30) NOT NULL,
    institucion varchar(255) NOT NULL,
    descripcion text NOT NULL,
    anio_inicio integer,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_investigador_experiencia UNIQUE (codigo_rh, descripcion)
);

CREATE TABLE IF NOT EXISTS public.investigador_areas_actuacion (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    investigador_id bigint NOT NULL REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_rh varchar(30) NOT NULL,
    gran_area varchar(150) NOT NULL,
    area varchar(150),
    subarea varchar(150),
    texto_completo text NOT NULL,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_investigador_area UNIQUE (codigo_rh, texto_completo)
);

CREATE TABLE IF NOT EXISTS public.investigador_idiomas (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    investigador_id bigint NOT NULL REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_rh varchar(30) NOT NULL,
    idioma varchar(60) NOT NULL,
    habla varchar(40),
    escribe varchar(40),
    lee varchar(40),
    entiende varchar(40),
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_investigador_idioma UNIQUE (codigo_rh, idioma)
);

CREATE TABLE IF NOT EXISTS public.investigador_reconocimientos (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    investigador_id bigint NOT NULL REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_rh varchar(30) NOT NULL,
    descripcion text NOT NULL,
    anio integer,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_investigador_reconocimiento UNIQUE (codigo_rh, descripcion)
);

CREATE TABLE IF NOT EXISTS public.investigador_redes_identificadores (
    id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    investigador_id bigint NOT NULL REFERENCES public.investigadores(id) ON DELETE CASCADE,
    codigo_rh varchar(30) NOT NULL,
    tipo varchar(60) NOT NULL,
    nombre varchar(150) NOT NULL,
    url text NOT NULL,
    activo boolean NOT NULL DEFAULT true,
    es_ejemplo boolean NOT NULL DEFAULT false,
    creado_en timestamptz NOT NULL DEFAULT now(),
    actualizado_en timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uk_investigador_red_id UNIQUE (codigo_rh, tipo, nombre)
);

