INSERT INTO public.productos (
    codigo_identificador, titulo, tipo_mayor, subtipo, ano, mes, pais,
    estado_validacion, detalles, activo, es_ejemplo
) VALUES (
    'CVL494917-PRY-0007', 'Investigación y desarrollo EVALUACIÓN DE LA PRODUCTIVIDAD DE LOS CULTIVOS DE CAFÉS ESPECIALES MEDIANTE LA OPTIMIZACIÓN DE MODELOS DE RIESGOS AGROCLIMÁTICOS Inicio: Enero 2017 Fin: Agosto 2018 Duración Resumen En el actual contexto de negocios es de vital importancia aumentar la productividad y compe', 'FRH',
    'Proyecto de I+D', 2017, 1, 'Colombia',
    'Con soporte', '{"origen": "CvLAC", "codigo_rh_titular": "0000494917", "seccion_tabla": 38, "seccion_nombre": "Proyectos", "numero_en_seccion": 7, "encabezado_item": "Tipo de proyecto: Extensión y responsabilidad social CTI Metro de Medellin Inicio: Duración Resumen", "texto_completo": "Tipo de proyecto: Extensión y responsabilidad social CTI Metro de Medellin Inicio: Duración Resumen — Tipo de proyecto: Investigación y desarrollo EVALUACIÓN DE LA PRODUCTIVIDAD DE LOS CULTIVOS DE CAFÉS ESPECIALES MEDIANTE LA OPTIMIZACIÓN DE MODELOS DE RIESGOS AGROCLIMÁTICOS Inicio: Enero 2017 Fin: Agosto 2018 Duración Resumen En el actual contexto de negocios es de vital importancia aumentar la productividad y competitividad de las organizaciones. El sector agropecuario está afectado por los factores climáticos que inciden de manera determinante en la productividad de los cultivos. El proyecto de investigación tiene como objetivo mejorar el rendimiento de los cultivos de cafés especiales mediante la optimización de los modelos de riesgo agroclimático, para tal fin, se analizarán los diferentes modelos de riesgos agroclimáticos. Posteriormente, se caracterizarán las unidades productivas en función de los modelos en referencia, para determinar el manejo óptimo de los cultivos de cafés especiales. Asimismo, se implementará el modelo planteado mediante una prueba piloto en una unidad productiva de la asociación ASOPROKIA. El presente proyecto es de tipo correlacional. El análisis de los datos se realizará mediante técnicas estadísticas, modelos de regresión, minería de datos, simulación y técnicas de optimización de acuerdo con la naturaleza de las variables de los modelos. El modelo de optimización se analizará mediante cómputo distribuido. Los resultados se orientan al mejoramiento de la productividad de los cultivos mediante la determinación del modelo de optimización para la productividad de los cafés especiales y su implementación, mediante prueba piloto, en una unidad productiva de la asociación objeto de estudio. Esta investigación, tienen un impacto desde el punto de vista práctico, debido a que se espera generar una innovación en el proceso de producción, aumentando la productividad promedio por hectárea a partir del análisis de las variables de riesgos agroclimáticos. Además, desde el punto de vista teórico, se propondrá un modelo de riesgo agroclimático adaptado y calibrado a los datos locales, para utilización por parte de los productos de la asociación de cafés especiales"}'::jsonb, true, false
) ON CONFLICT (codigo_identificador) DO UPDATE SET
    titulo = EXCLUDED.titulo,
    tipo_mayor = EXCLUDED.tipo_mayor,
    subtipo = EXCLUDED.subtipo,
    ano = EXCLUDED.ano,
    estado_validacion = EXCLUDED.estado_validacion,
    detalles = EXCLUDED.detalles,
    activo = true,
    es_ejemplo = false;
