INSERT INTO public.productos (
    codigo_identificador, titulo, tipo_mayor, subtipo, ano, mes, pais,
    estado_validacion, detalles, activo, es_ejemplo
) VALUES (
    'CVL494917-PRY-0009', 'Investigación y desarrollo Estudio para la determinación de la contribución de fuentes a la contaminación del aire intramural en las poblaciones aledañas a la vía férrea en Bosconia, Cesar, Colombia. Inicio: Noviembre 2016 Duración Resumen Esta propuesta de investigación contiene los elementos técni', 'FRH',
    'Proyecto de I+D', 2014, 1, 'Colombia',
    'Avalado', '{"origen": "CvLAC", "codigo_rh_titular": "0000494917", "seccion_tabla": 38, "seccion_nombre": "Proyectos", "numero_en_seccion": 9, "encabezado_item": "Tipo de proyecto: Investigación y desarrollo Software de Gestión de Recursos Humanos Inicio: Agosto 2014 Fin: Diciembre 2015 Duración Resumen Software para la gestion de inventarios de material EPP, Registro de Marcación, control de Alcoholemia.", "texto_completo": "Tipo de proyecto: Investigación y desarrollo Software de Gestión de Recursos Humanos Inicio: Agosto 2014 Fin: Diciembre 2015 Duración Resumen Software para la gestion de inventarios de material EPP, Registro de Marcación, control de Alcoholemia. — Tipo de proyecto: Investigación y desarrollo Estudio para la determinación de la contribución de fuentes a la contaminación del aire intramural en las poblaciones aledañas a la vía férrea en Bosconia, Cesar, Colombia. Inicio: Noviembre 2016 Duración Resumen Esta propuesta de investigación contiene los elementos técnico-científicos necesarios para la aplicación de modelos de dinámica del aire en intramuros por primera vez en Colombia y basados en metodologías recientemente demostradas en Chile (Barraza et al. 2014). Este nuevo estudio extenderá y refinará estas metodologías, al mismo tiempo que aportará información esencial para tomar medidas en pro del mejoramiento de las condiciones ambientales y de salud en la zona carbonífera del Cesar, donde a la fecha no se han llevado a cabo estudios de este tipo. Estas metodologías serán después diseminadas a nivel nacional. Se considerarán fuentes importantes, tales como actividades ferroviarias, así como otras actividades de transporte y residenciales. Se ejecutarán modelos de calidad del aire intramural por primera vez en esta zona de influencia de transporte férreo de carbón mineral y con impacto de diversas fuentes. Se llevarán a cabo monitoreos y caracterización química de muestras a partir de esos resultados se espera establecer el aporte de la actividad de transporte férreo en la zona de estudio. El valor total del proyecto es de $45 millones de los cuales se solicitan $30 millones en efectivo a la UPC."}'::jsonb, true, false
) ON CONFLICT (codigo_identificador) DO UPDATE SET
    titulo = EXCLUDED.titulo,
    tipo_mayor = EXCLUDED.tipo_mayor,
    subtipo = EXCLUDED.subtipo,
