    'Con soporte', '{"origen": "CvLAC", "codigo_rh_titular": "0000494917", "seccion_tabla": 16, "seccion_nombre": "Eventos científicos", "numero_en_seccion": 11, "texto_completo": "11 Nombre del evento: Ingennio 2018 Conferencia Internacional de Ingeniería Tipo de evento: Congreso Ámbito: Internacional Realizado el:2018-08-22 00:00:00.0, 2018-12-24 00:00:00.0 en MEDELLÍN - Politecnico Grancolombiano Productos asociados Nombre del producto:Análisis de la investigación, desarrollo e innovación en Colombia desde una perspectiva compleja Tipo de producto:Producción técnica - Presentación de trabajo - Ponencia Instituciones asociadas Nombre de la institución:Universidad De Santander - Campus Valledupar Tipo de vinculaciónPatrocinadora Participantes Nombre: ADITH BISMARCK PEREZ OROZCO Rol en el evento: Ponente"}'::jsonb, true, false
) ON CONFLICT (codigo_identificador) DO UPDATE SET
    titulo = EXCLUDED.titulo,
    tipo_mayor = EXCLUDED.tipo_mayor,
    subtipo = EXCLUDED.subtipo,
    ano = EXCLUDED.ano,
    estado_validacion = EXCLUDED.estado_validacion,
    detalles = EXCLUDED.detalles,
    activo = true,
    es_ejemplo = false;

-- 7. VINCULACIÓN DE PRODUCTOS CON EL GRUPO GISICO (producto_grupos)
INSERT INTO public.producto_grupos (producto_id, grupo_id, activo, es_ejemplo)
SELECT p.id, g.id, true, false
FROM public.productos p
CROSS JOIN public.grupos g
WHERE p.es_ejemplo = false AND g.codigo_gruplac = '00000000002099'
ON CONFLICT (producto_id, grupo_id) DO NOTHING;

